bool mp_image_bilipai_token_matches(const struct mp_image *img)
{
    if (!img || !mp_bilipai_token_valid(&img->bilipai_rtx))
        return false;
    const struct mp_bilipai_frame_token *t = &img->bilipai_rtx;
    if (img->imgfmt != IMGFMT_D3D11 || img->w != t->width || img->h != t->height ||
        img->params.w != t->width || img->params.h != t->height ||
        img->params.repr.sys != PL_COLOR_SYSTEM_RGB ||
        img->params.repr.levels != PL_COLOR_LEVELS_FULL ||
        !isfinite(img->pts) || img->pts == MP_NOPTS_VALUE ||
        fabs(img->pts) >= (double)INT64_MAX / t->pts_denominator ||
        llround(img->pts * t->pts_denominator) != t->pts_numerator)
        return false;
    if (t->transport == MP_BILIPAI_SRGB_BGRA8)
        return img->params.hw_subfmt == IMGFMT_BGRA &&
               img->params.color.primaries == PL_COLOR_PRIM_BT_709 &&
               img->params.color.transfer == PL_COLOR_TRC_SRGB;
    return img->params.hw_subfmt == IMGFMT_X2BGR10 &&
           img->params.color.primaries == PL_COLOR_PRIM_BT_2020 &&
           img->params.color.transfer == PL_COLOR_TRC_PQ &&
           img->params.color.hdr.max_luma == t->hdr_peak_nits;
}

