    if (p->opts->sync_interval != 1 || sw->ctx->opts.composition ||
        GetSystemMetrics(SM_CMONITORS) != 1)
        return false;
    HWND w = vo_w32_hwnd(sw->ctx->vo);
    HMONITOR mon = MonitorFromWindow(w, MONITOR_DEFAULTTONULL);
    MONITORINFO info = {.cbSize = sizeof(info)};
    DXGI_SWAP_CHAIN_DESC desc = {0};
    if (!w || !mon || mon != p->bilipai_monitor ||
        !GetMonitorInfo(mon, &info) ||
        IDXGISwapChain_GetDesc(p->swapchain, &desc) != S_OK ||
        (desc.SwapEffect != DXGI_SWAP_EFFECT_FLIP_SEQUENTIAL &&
         desc.SwapEffect != DXGI_SWAP_EFFECT_FLIP_DISCARD))
        return false;
    struct bilipai_fullscreen_probe probe = {.monitor = info.rcMonitor};
    return EnumWindows(bilipai_foreign_fullscreen, (LPARAM)&probe) &&
