}
static bool bilipai_output(struct ra_swapchain *sw,
                          const struct mp_bilipai_render_receipt *r,
                          struct mp_bilipai_present_receipt *out)
{
    struct priv *p = sw->priv;
    DXGI_SWAP_CHAIN_DESC desc = {0};
    if (!r->fresh || !mp_bilipai_token_valid(&r->token) ||
        !p->bilipai_color_configured || !p->bilipai_adapter_luid ||
        r->token.adapter_luid != p->bilipai_adapter_luid ||
        r->target_transfer != p->swapchain_csp.transfer ||
        r->target_primaries != p->swapchain_csp.primaries ||
        r->framebuffer_transfer != p->swapchain_csp.transfer ||
        r->framebuffer_primaries != p->swapchain_csp.primaries ||
        IDXGISwapChain_GetDesc(p->swapchain, &desc) != S_OK)
        return false;
    bool hdr = !!(r->token.effects & MP_BILIPAI_EFFECT_HDR);
    bool hdr_proved = false;
    if (hdr) {
        DXGI_OUTPUT_DESC1 display = {0};
        bool hdr_encoding =
            (desc.BufferDesc.Format == DXGI_FORMAT_R10G10B10A2_UNORM &&
             p->bilipai_dxgi_csp == DXGI_COLOR_SPACE_RGB_FULL_G2084_NONE_P2020) ||
            (desc.BufferDesc.Format == DXGI_FORMAT_R16G16B16A16_FLOAT &&
             p->bilipai_dxgi_csp == DXGI_COLOR_SPACE_RGB_FULL_G10_NONE_P709);
        hdr_proved = hdr_encoding && !sw->ctx->opts.composition &&
            mp_dxgi_output_desc_from_hwnd(&p->dxgi_ctx, vo_w32_hwnd(sw->ctx->vo), &display) &&
            display.ColorSpace == DXGI_COLOR_SPACE_RGB_FULL_G2084_NONE_P2020;
        if (!hdr_proved) return false;
    }
    *out = (struct mp_bilipai_present_receipt){
        .render = *r, .epoch = p->bilipai_feedback.epoch,
        .dxgi_format = desc.BufferDesc.Format, .dxgi_color_space = p->bilipai_dxgi_csp,
        .hdr_output_proved = hdr_proved,
    };
    return true;
}
static bool bilipai_same_generation(const struct mp_bilipai_frame_token *a,
                                    const struct mp_bilipai_frame_token *b)
{
    return a->session == b->session && a->configuration == b->configuration &&
           a->stream == b->stream && a->adapter_luid == b->adapter_luid;
}
static void bilipai_update_statistics(struct ra_swapchain *sw)
{
    struct priv *p = sw->priv;
    if (p->bilipai_counter_failed || !p->bilipai_feedback.queued.valid)
        return;
    if (!bilipai_statistics_environment(sw)) {
        p->bilipai_feedback.displayed.valid = false;
        p->bilipai_feedback.reason = MP_BILIPAI_PROOF_UNSUPPORTED;
        return;
    }
    DXGI_FRAME_STATISTICS stats = {0};
    HRESULT hr = IDXGISwapChain_GetFrameStatistics(p->swapchain, &stats);
    p->bilipai_feedback.statistics_hresult = hr;
    if (hr == DXGI_ERROR_FRAME_STATISTICS_DISJOINT) {
        struct mp_bilipai_present_receipt queued = p->bilipai_feedback.queued;
        bilipai_invalidate(p, MP_BILIPAI_PROOF_DISJOINT, true);
        // Preserve only truthful queue acceptance; previous display sequence is gone.
        queued.epoch = p->bilipai_feedback.epoch;
        p->bilipai_feedback.queued = queued;
        return;
    }
    if (hr != S_OK || !stats.PresentCount || !stats.PresentRefreshCount ||
        !stats.SyncRefreshCount || stats.SyncQPCTime.QuadPart <= 0) {
        p->bilipai_feedback.displayed.valid = false;
        return;
    }
    for (unsigned n = 0; n < VO_MAX_SWAPCHAIN_DEPTH; ++n) {
        const struct mp_bilipai_present_receipt *entry = &p->bilipai_ring[n];
        if (!entry->valid || entry->epoch != p->bilipai_feedback.epoch ||
            entry->present_count != stats.PresentCount ||
            !bilipai_same_generation(&entry->render.token,
                                     &p->bilipai_feedback.queued.render.token))
            continue;
        if (p->bilipai_feedback.displayed.valid &&
            p->bilipai_feedback.displayed.present_count == entry->present_count &&
            mp_bilipai_token_equal(&p->bilipai_feedback.displayed.render.token,
                                  &entry->render.token))
            return;
        p->bilipai_feedback.displayed = *entry;
        p->bilipai_feedback.displayed.refresh_count = stats.PresentRefreshCount;
        p->bilipai_feedback.displayed.sync_qpc = stats.SyncQPCTime.QuadPart;
        p->bilipai_feedback.reason = MP_BILIPAI_PROOF_DISPLAY_MATCH;
        bilipai_step(p);
        return;
    }
    // Unknown/dropped/overwritten IDs cannot inherit another frame's evidence.
    p->bilipai_feedback.displayed.valid = false;
}
static void d3d11_bilipai_prepare(struct ra_swapchain *sw,
                                 const struct mp_bilipai_render_receipt *r,
                                 bool invalidate)
{
    struct priv *p = sw->priv;
    p->bilipai_pending = (struct mp_bilipai_render_receipt){0};
    if (invalidate) {
        bilipai_invalidate(p, MP_BILIPAI_PROOF_UNPROVEN, false);
        return;
    }
    if (r && r->fresh && mp_bilipai_token_valid(&r->token) &&
        !p->bilipai_counter_failed) {
        if (p->bilipai_feedback.queued.valid &&
            !bilipai_same_generation(&r->token,
                                     &p->bilipai_feedback.queued.render.token))
            bilipai_invalidate(p, MP_BILIPAI_PROOF_UNPROVEN, true);
        p->bilipai_pending = *r;
    }
}
